// src/pages/Login.jsx
import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate, Link } from 'react-router-dom';
import './Login.css';

function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    
    try {
      console.log('🔐 Tentative de connexion avec:', { email, password });
      
      const res = await axios.post('http://localhost:5000/api/auth/login', { email, password });
      
      console.log('✅ Réponse complète du serveur:', res.data);
      
      // Vérification approfondie de la structure
      if (res.data && res.data.success) {
        console.log('🎯 Données trouvées dans res.data');
        
        // PLUSIEURS STRUCTURES POSSIBLES - On teste tout
        const token = res.data.token || (res.data.data && res.data.data.token);
        const user = res.data.user || (res.data.data && res.data.data.user);
        
        console.log('🔑 Token extrait:', token);
        console.log('👤 User extrait:', user);
        
        if (token && user) {
          // Sauvegarder
          localStorage.setItem('token', token);
          localStorage.setItem('user', JSON.stringify(user));
          
          console.log('💾 Données sauvegardées dans localStorage');
          console.log('🔍 Vérification localStorage:');
          console.log('- Token:', localStorage.getItem('token'));
          console.log('- User:', localStorage.getItem('user'));
          
          // Redirection basée sur le rôle
          const userRole = user.role;
          console.log('🎭 Rôle détecté:', userRole);
          
          if (userRole === 'student') {
            console.log('🎓 Redirection vers dashboard étudiant');
            navigate('/dashboard-student');
          } else if (userRole === 'prof') {
            console.log('👨‍🏫 Redirection vers dashboard prof');
            navigate('/dashboard-prof');
          } else {
            console.log('❌ Rôle non reconnu, redirection par défaut');
            navigate('/dashboard-prof');
          }
        } else {
          console.log('❌ Token ou user manquant');
          alert('Données de connexion incomplètes');
        }
      } else {
        console.log('❌ Structure de réponse incorrecte - res.data:', res.data);
        alert(res.data?.message || 'Erreur de connexion - Structure incorrecte');
      }
      
    } catch (err) {
      console.error('💥 Erreur de connexion:', err);
      console.log('📡 Réponse erreur:', err.response?.data);
      console.log('🔧 Statut:', err.response?.status);
      
      // Message d'erreur amélioré
      const errorMessage = err.response?.data?.message || 
                          err.response?.data?.msg || 
                          'Email ou mot de passe incorrect';
      
      alert(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  // TEST MANUEL - Décommente pour tester sans backend
  const handleTestLogin = () => {
    console.log('🧪 TEST MANUEL - Connexion simulée');
    
    const mockUser = {
      id: '123',
      nom: 'Professeur Test',
      email: 'test@prof.com',
      role: 'prof'
    };
    
    localStorage.setItem('token', 'mock-token-123');
    localStorage.setItem('user', JSON.stringify(mockUser));
    
    console.log('✅ Données mock sauvegardées');
    console.log('🔍 localStorage:', {
      token: localStorage.getItem('token'),
      user: localStorage.getItem('user')
    });
    
    navigate('/dashboard-prof');
  };

  return (
    <div className="login-container">
      <div className="login-card">
        <div className="login-header">
          <h2>Content de vous revoir</h2>
          <p>Connectez-vous à votre compte</p>
        </div>

        <form onSubmit={handleLogin} className="login-form">
          <div className="form-group">
            <label htmlFor="email">Adresse email</label>
            <input 
              id="email"
              type="email" 
              placeholder="exemple@email.com" 
              value={email} 
              onChange={e => setEmail(e.target.value)} 
              required 
              className="form-input"
            />
          </div>

          <div className="form-group">
            <div className="password-label-container">
              <label htmlFor="password">Mot de passe</label>
              <Link to="/forgot-password" className="forgot-password">
                Mot de passe oublié ?
              </Link>
            </div>
            <input 
              id="password"
              type="password" 
              placeholder="Votre mot de passe" 
              value={password} 
              onChange={e => setPassword(e.target.value)} 
              required 
              className="form-input"
            />
          </div>

          <button 
            type="submit" 
            className={`submit-btn ${isLoading ? 'loading' : ''}`}
            disabled={isLoading}
          >
            {isLoading ? (
              <>
                <span className="spinner"></span>
                Connexion en cours...
              </>
            ) : (
              'Se connecter'
            )}
          </button>
        </form>

        {/* BOUTON TEST - Décommente pour tester */}
        <div style={{ textAlign: 'center', margin: '20px 0' }}>
          <button 
            onClick={handleTestLogin}
            style={{
              background: '#10B981',
              color: 'white',
              border: 'none',
              padding: '10px 20px',
              borderRadius: '8px',
              cursor: 'pointer'
            }}
          >
            🧪 TEST - Connexion Auto
          </button>
        </div>

        <div className="login-footer">
          <div className="separator">
            <span>Nouveau sur la plateforme ?</span>
          </div>
          <Link to="/register" className="register-link">
            Créer un compte
          </Link>
        </div>

        <div className="demo-accounts">
          <details className="demo-section">
            <summary>Comptes de démonstration</summary>
            <div className="demo-cards">
              <div className="demo-card">
                <h4>👨‍🎓 Étudiant</h4>
                <p><strong>Email:</strong> etudiant@demo.com</p>
                <p><strong>Mot de passe:</strong> 123456</p>
              </div>
              <div className="demo-card">
                <h4>👨‍🏫 Professeur</h4>
                <p><strong>Email:</strong> prof@demo.com</p>
                <p><strong>Mot de passe:</strong> 123456</p>
              </div>
            </div>
          </details>
        </div>
      </div>
    </div>
  );
}

export default Login;
